import{_ as e,o as r,c as a,a2 as o}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Mobile App","description":"","frontmatter":{},"headers":[],"relativePath":"trading-platform/mobile-app.md","filePath":"trading-platform/mobile-app.md"}'),n={name:"trading-platform/mobile-app.md"};function i(s,t,d,l,h,c){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="mobile-app" tabindex="-1">Mobile App <a class="header-anchor" href="#mobile-app" aria-label="Permalink to &quot;Mobile App&quot;">​</a></h1><p><strong>Tradeboard Terminal</strong> is a Flutter mobile trading app that connects to your own Tradeboard server. It is a <strong>frontend only</strong> application: it holds no broker credentials of its own, stores no data centrally, and talks exclusively to the server URL and API key you give it.</p><ul><li>Repository: <a href="https://github.com/wesoftcorp/tradeboard-mobile" target="_blank" rel="noreferrer">wesoftcorp/tradeboard-docs-mobile</a></li><li>Built with Flutter and Dart</li><li>Platforms: Android and Web</li><li>Licence: AGPL-3.0</li></ul><hr><h2 id="what-it-does" tabindex="-1">What It Does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What It Does&quot;">​</a></h2><h3 id="trading" tabindex="-1">Trading <a class="header-anchor" href="#trading" aria-label="Permalink to &quot;Trading&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th></tr></thead><tbody><tr><td><strong>Watchlist</strong></td><td>Track multiple instruments with real-time quotes</td></tr><tr><td><strong>Live market data</strong></td><td>Price updates on a rolling refresh</td></tr><tr><td><strong>Order management</strong></td><td>Place, modify and cancel orders</td></tr><tr><td><strong>Positions</strong></td><td>Monitor open positions and holdings</td></tr><tr><td><strong>Tradebook</strong></td><td>Full history of executions</td></tr><tr><td><strong>Market depth</strong></td><td>Level 2 order book</td></tr><tr><td><strong>Account overview</strong></td><td>Available cash, used margin and P&amp;L</td></tr></tbody></table><h3 id="other" tabindex="-1">Other <a class="header-anchor" href="#other" aria-label="Permalink to &quot;Other&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Description</th></tr></thead><tbody><tr><td><strong>Analyzer mode</strong></td><td>Switch between live and analyze (paper trading) without leaving the app</td></tr><tr><td><strong>Configurable header</strong></td><td>Choose the indices on the header, such as NIFTY, BANKNIFTY, SENSEX and INDIAVIX</td></tr><tr><td><strong>Themes</strong></td><td>Light and dark</td></tr></tbody></table><hr><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>You need a <strong>running Tradeboard server</strong> and an API key from its dashboard. The app is a client; it cannot trade on its own.</p><ul><li>Install Tradeboard from <a href="./../getting-started/README.html">Getting Started</a>, or</li><li>Point the app at a server you already run</li></ul><p>Then generate an API key from the <code>/apikey</code> page of that server.</p><hr><h2 id="connecting" tabindex="-1">Connecting <a class="header-anchor" href="#connecting" aria-label="Permalink to &quot;Connecting&quot;">​</a></h2><p>The app asks for two things on first run:</p><ol><li><strong>Server URL</strong>, for example <code>https://yourdomain.com</code> or your local address</li><li><strong>API key</strong>, from your Tradeboard dashboard</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Reaching a <strong>local</strong> Tradeboard install from a phone needs the server to be accessible from the phone&#39;s network. <code>127.0.0.1</code> refers to the phone itself, not your computer.</p><p>Use your machine&#39;s LAN address, or expose the server properly with one of the tunnelling or custom domain guides under <a href="./../getting-started/README.html">Getting Started</a>. Anything you expose publicly needs TLS and the usual hardening: the API key is the credential that resolves your broker session.</p></div><hr><h2 id="security-model" tabindex="-1">Security Model <a class="header-anchor" href="#security-model" aria-label="Permalink to &quot;Security Model&quot;">​</a></h2><p>The app follows the same principle as the rest of Tradeboard: <strong>your broker credentials never leave your server.</strong></p><ul><li>The app holds an <strong>Tradeboard API key</strong>, not broker credentials</li><li>The server resolves that key to the active broker session</li><li>Revoking the key from the dashboard cuts the app off without touching your broker account</li><li>No trading data passes through any third party</li></ul><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./chrome-extension.html">Chrome Extension</a> for browser-based order entry</li><li><a href="./../mini-foss-universe.html">Mini FOSS Universe</a> for the rest of the ecosystem</li><li><a href="./../getting-started/README.html">Getting Started</a> to set up the server the app connects to</li></ul>',26)])])}const g=e(n,[["render",i]]);export{u as __pageData,g as default};
